// generated by tools/build_verse_manifests.js from dc_english.js — Dual-view English for the chapters of dc_verses/dc21_30.js
registerEnglish([["D&C",21,1,"Behold, there shall be a record kept among you; and in it thou shalt be called a seer, a translator, a prophet, an apostle of Jesus Christ, an elder of the church through the will of God the Father, and the grace of your Lord Jesus Christ,"],["D&C",21,2,"Being inspired of the Holy Ghost to lay the foundation thereof, and to build it up unto the most holy faith."],["D&C",21,3,"Which church was organized and established in the year of your Lord eighteen hundred and thirty, in the fourth month, and on the sixth day of the month which is called April."],["D&C",21,4,"Wherefore, meaning the church, thou shalt give heed unto all his words and commandments which he shall give unto you as he receiveth them, walking in all holiness before me;"],["D&C",21,5,"For his word ye shall receive, as if from mine own mouth, in all patience and faith."],["D&C",21,6,"For by doing these things the gates of hell shall not prevail against you; yea, and the Lord God will disperse the powers of darkness from before you, and cause the heavens to shake for your good, and his name's glory."],["D&C",21,7,"For thus saith the Lord God: Him have I inspired to move the cause of Zion in mighty power for good, and his diligence I know, and his prayers I have heard."],["D&C",21,8,"Yea, his weeping for Zion I have seen, and I will cause that he shall mourn for her no longer; for his days of rejoicing are come unto the remission of his sins, and the manifestations of my blessings upon his works."],["D&C",21,9,"For, behold, I will bless all those who labor in my vineyard with a mighty blessing, and they shall believe on his words, which are given him through me by the Comforter, which manifesteth that Jesus was crucified by sinful men for the sins of the world, yea, for the remission of sins unto the contrite heart."],["D&C",21,10,"Wherefore it behooveth me that he should be ordained by you, Oliver Cowdery mine apostle;"],["D&C",21,11,"This being an ordinance unto you, that you are an elder under his hand, he being the first unto you, that you might be an elder unto this church of Christ, bearing my name—"],["D&C",21,12,"And the first preacher of this church unto the church, and before the world, yea, before the Gentiles; yea, and thus saith the Lord God, lo, lo! to the Jews also. Amen."],["D&C",22,1,"Behold, I say unto you that all old covenants have I caused to be done away in this thing; and this is a new and an everlasting covenant, even that which was from the beginning."],["D&C",22,2,"Wherefore, although a man should be baptized an hundred times it availeth him nothing, for you cannot enter in at the strait gate by the law of Moses, neither by your dead works."],["D&C",22,3,"For it is because of your dead works that I have caused this last covenant and this church to be built up unto me, even as in days of old."],["D&C",22,4,"Wherefore, enter ye in at the gate, as I have commanded, and seek not to counsel your God. Amen."],["D&C",23,1,"Behold, I speak unto you, Oliver, a few words. Behold, thou art blessed, and art under no condemnation. But beware of pride, lest thou shouldst enter into temptation."],["D&C",23,2,"Make known thy calling unto the church, and also before the world, and thy heart shall be opened to preach the truth from henceforth and forever. Amen."],["D&C",23,3,"Behold, I speak unto you, Hyrum, a few words; for thou also art under no condemnation, and thy heart is opened, and thy tongue loosed; and thy calling is to exhortation, and to strengthen the church continually. Wherefore thy duty is unto the church forever, and this because of thy family. Amen."],["D&C",23,4,"Behold, I speak a few words unto you, Samuel; for thou also art under no condemnation, and thy calling is to exhortation, and to strengthen the church; and thou art not as yet called to preach before the world. Amen."],["D&C",23,5,"Behold, I speak a few words unto you, Joseph; for thou also art under no condemnation, and thy calling also is to exhortation, and to strengthen the church; and this is thy duty from henceforth and forever. Amen."],["D&C",23,6,"Behold, I manifest unto you, Joseph Knight, by these words, that you must take up your cross, in the which you must pray vocally before the world as well as in secret, and in your family, and among your friends, and in all places."],["D&C",23,7,"And, behold, it is your duty to unite with the true church, and give your language to exhortation continually, that you may receive the reward of the laborer. Amen."],["D&C",24,1,"Behold, thou wast called and chosen to write the Book of Mormon, and to my ministry; and I have lifted thee up out of thine afflictions, and have counseled thee, that thou hast been delivered from all thine enemies, and thou hast been delivered from the powers of Satan and from darkness!"],["D&C",24,2,"Nevertheless, thou art not excusable in thy transgressions; nevertheless, go thy way and sin no more."],["D&C",24,3,"Magnify thine office; and after thou hast sowed thy fields and secured them, go speedily unto the church which is in Colesville, Fayette, and Manchester, and they shall support thee; and I will bless them both spiritually and temporally;"],["D&C",24,4,"But if they receive thee not, I will send upon them a cursing instead of a blessing."],["D&C",24,5,"And thou shalt continue in calling upon God in my name, and writing the things which shall be given thee by the Comforter, and expounding all scriptures unto the church."],["D&C",24,6,"And it shall be given thee in the very moment what thou shalt speak and write, and they shall hear it, or I will send unto them a cursing instead of a blessing."],["D&C",24,7,"For thou shalt devote all thy service in Zion; and in this thou shalt have strength."],["D&C",24,8,"Be patient in afflictions, for thou shalt have many; but endure them, for, lo, I am with thee, even unto the end of thy days."],["D&C",24,9,"And in temporal labors thou shalt not have strength, for this is not thy calling. Attend to thy calling and thou shalt have wherewith to magnify thine office, and to expound all scriptures, and continue in laying on of the hands and confirming the churches."],["D&C",24,10,"And thy brother Oliver shall continue in bearing my name before the world, and also to the church. And he shall not suppose that he can say enough in my cause; and lo, I am with him to the end."],["D&C",24,11,"In me he shall have glory, and not of himself, whether in weakness or in strength, whether in bonds or free;"],["D&C",24,12,"And at all times, and in all places, he shall open his mouth and declare my gospel as with the voice of a trump, both day and night. And I will give unto him strength such as is not known among men."],["D&C",24,13,"Require not miracles, except I shall command you, except casting out devils, healing the sick, and against poisonous serpents, and against deadly poisons;"],["D&C",24,14,"And these things ye shall not do, except it be required of you by them who desire it, that the scriptures might be fulfilled; for ye shall do according to that which is written."],["D&C",24,15,"And in whatsoever place ye shall enter, and they receive you not in my name, ye shall leave a cursing instead of a blessing, by casting off the dust of your feet against them as a testimony, and cleansing your feet by the wayside."],["D&C",24,16,"And it shall come to pass that whosoever shall lay their hands upon you by violence, ye shall command to be smitten in my name; and, behold, I will smite them according to your words, in mine own due time."],["D&C",24,17,"And whosoever shall go to law with thee shall be cursed by the law."],["D&C",24,18,"And thou shalt take no purse nor scrip, neither staves, neither two coats, for the church shall give unto thee in the very hour what thou needest for food and for raiment, and for shoes and for money, and for scrip."],["D&C",24,19,"For thou art called to prune my vineyard with a mighty pruning, yea, even for the last time; yea, and also all those whom thou hast ordained, and they shall do even according to this pattern. Amen."],["D&C",25,1,"Hearken unto the voice of the Lord your God, while I speak unto you, Emma Smith, my daughter; for verily I say unto you, all those who receive my gospel are sons and daughters in my kingdom."],["D&C",25,2,"A revelation I give unto you concerning my will; and if thou art faithful and walk in the paths of virtue before me, I will preserve thy life, and thou shalt receive an inheritance in Zion."],["D&C",25,3,"Behold, thy sins are forgiven thee, and thou art an elect lady, whom I have called."],["D&C",25,4,"Murmur not because of the things which thou hast not seen, for they are withheld from thee and from the world, which is wisdom in me in a time to come."],["D&C",25,5,"And the office of thy calling shall be for a comfort unto my servant, Joseph Smith, Jun., thy husband, in his afflictions, with consoling words, in the spirit of meekness."],["D&C",25,6,"And thou shalt go with him at the time of his going, and be unto him for a scribe, while there is no one to be a scribe for him, that I may send my servant, Oliver Cowdery, whithersoever I will."],["D&C",25,7,"And thou shalt be ordained under his hand to expound scriptures, and to exhort the church, according as it shall be given thee by my Spirit."],["D&C",25,8,"For he shall lay his hands upon thee, and thou shalt receive the Holy Ghost, and thy time shall be given to writing, and to learning much."],["D&C",25,9,"And thou needest not fear, for thy husband shall support thee in the church; for unto them is his calling, that all things might be revealed unto them, whatsoever I will, according to their faith."],["D&C",25,10,"And verily I say unto thee that thou shalt lay aside the things of this world, and seek for the things of a better."],["D&C",25,11,"And it shall be given thee, also, to make a selection of sacred hymns, as it shall be given thee, which is pleasing unto me, to be had in my church."],["D&C",25,12,"For my soul delighteth in the song of the heart; yea, the song of the righteous is a prayer unto me, and it shall be answered with a blessing upon their heads."],["D&C",25,13,"Wherefore, lift up thy heart and rejoice, and cleave unto the covenants which thou hast made."],["D&C",25,14,"Continue in the spirit of meekness, and beware of pride. Let thy soul delight in thy husband, and the glory which shall come upon him."],["D&C",25,15,"Keep my commandments continually, and a crown of righteousness thou shalt receive. And except thou do this, where I am you cannot come."],["D&C",25,16,"And verily, verily, I say unto you, that this is my voice unto all. Amen."],["D&C",26,1,"Behold, I say unto you that you shall let your time be devoted to the studying of the scriptures, and to preaching, and to confirming the church at Colesville, and to performing your labors on the land, such as is required, until after you shall go to the west to hold the next conference; and then it shall be made known what you shall do."],["D&C",26,2,"And all things shall be done by common consent in the church, by much prayer and faith, for all things you shall receive by faith. Amen."],["D&C",27,1,"Listen to the voice of Jesus Christ, your Lord, your God, and your Redeemer, whose word is quick and powerful."],["D&C",27,2,"For, behold, I say unto you, that it mattereth not what ye shall eat or what ye shall drink when ye partake of the sacrament, if it so be that ye do it with an eye single to my glory—remembering unto the Father my body which was laid down for you, and my blood which was shed for the remission of your sins."],["D&C",27,3,"Wherefore, a commandment I give unto you, that you shall not purchase wine neither strong drink of your enemies;"],["D&C",27,4,"Wherefore, you shall partake of none except it is made new among you; yea, in this my Father's kingdom which shall be built up on the earth."],["D&C",27,5,"Behold, this is wisdom in me; wherefore, marvel not, for the hour cometh that I will drink of the fruit of the vine with you on the earth, and with Moroni, whom I have sent unto you to reveal the Book of Mormon, containing the fulness of my everlasting gospel, to whom I have committed the keys of the record of the stick of Ephraim;"],["D&C",27,6,"And also with Elias, to whom I have committed the keys of bringing to pass the restoration of all things spoken by the mouth of all the holy prophets since the world began, concerning the last days;"],["D&C",27,7,"And also John the son of Zacharias, which Zacharias he (Elias) visited and gave promise that he should have a son, and his name should be John, and he should be filled with the spirit of Elias;"],["D&C",27,8,"Which John I have sent unto you, my servants, Joseph Smith, Jun., and Oliver Cowdery, to ordain you unto the first priesthood which you have received, that you might be called and ordained even as Aaron;"],["D&C",27,9,"And also Elijah, unto whom I have committed the keys of the power of turning the hearts of the fathers to the children, and the hearts of the children to the fathers, that the whole earth may not be smitten with a curse;"],["D&C",27,10,"And also with Joseph and Jacob, and Isaac, and Abraham, your fathers, by whom the promises remain;"],["D&C",27,11,"And also with Michael, or Adam, the father of all, the prince of all, the ancient of days;"],["D&C",27,12,"And also with Peter, and James, and John, whom I have sent unto you, by whom I have ordained you and confirmed you to be apostles, and especial witnesses of my name, and bear the keys of your ministry and of the same things which I revealed unto them;"],["D&C",27,13,"Unto whom I have committed the keys of my kingdom, and a dispensation of the gospel for the last times; and for the fulness of times, in the which I will gather together in one all things, both which are in heaven, and which are on earth;"],["D&C",27,14,"And also with all those whom my Father hath given me out of the world."],["D&C",27,15,"Wherefore, lift up your hearts and rejoice, and gird up your loins, and take upon you my whole armor, that ye may be able to withstand the evil day, having done all, that ye may be able to stand."],["D&C",27,16,"Stand, therefore, having your loins girt about with truth, having on the breastplate of righteousness, and your feet shod with the preparation of the gospel of peace, which I have sent mine angels to commit unto you;"],["D&C",27,17,"Taking the shield of faith wherewith ye shall be able to quench all the fiery darts of the wicked;"],["D&C",27,18,"And take the helmet of salvation, and the sword of my Spirit, which I will pour out upon you, and my word which I reveal unto you, and be agreed as touching all things whatsoever ye ask of me, and be faithful until I come, and ye shall be caught up, that where I am ye shall be also. Amen."],["D&C",28,1,"Behold, I say unto thee, Oliver, that it shall be given unto thee that thou shalt be heard by the church in all things whatsoever thou shalt teach them by the Comforter, concerning the revelations and commandments which I have given."],["D&C",28,2,"But, behold, verily, verily, I say unto thee, no one shall be appointed to receive commandments and revelations in this church excepting my servant Joseph Smith, Jun., for he receiveth them even as Moses."],["D&C",28,3,"And thou shalt be obedient unto the things which I shall give unto him, even as Aaron, to declare faithfully the commandments and the revelations, with power and authority unto the church."],["D&C",28,4,"And if thou art led at any time by the Comforter to speak or teach, or at all times by the way of commandment unto the church, thou mayest do it."],["D&C",28,5,"But thou shalt not write by way of commandment, but by wisdom;"],["D&C",28,6,"And thou shalt not command him who is at thy head, and at the head of the church;"],["D&C",28,7,"For I have given him the keys of the mysteries, and the revelations which are sealed, until I shall appoint unto them another in his stead."],["D&C",28,8,"And now, behold, I say unto you that you shall go unto the Lamanites and preach my gospel unto them; and inasmuch as they receive thy teachings thou shalt cause my church to be established among them; and thou shalt have revelations, but write them not by way of commandment."],["D&C",28,9,"And now, behold, I say unto you that it is not revealed, and no man knoweth where the city Zion shall be built, but it shall be given hereafter. Behold, I say unto you that it shall be on the borders by the Lamanites."],["D&C",28,10,"Thou shalt not leave this place until after the conference; and my servant Joseph shall be appointed to preside over the conference by the voice of it, and what he saith to thee thou shalt tell."],["D&C",28,11,"And again, thou shalt take thy brother, Hiram Page, between him and thee alone, and tell him that those things which he hath written from that stone are not of me and that Satan deceiveth him;"],["D&C",28,12,"For, behold, these things have not been appointed unto him, neither shall anything be appointed unto any of this church contrary to the church covenants."],["D&C",28,13,"For all things must be done in order, and by common consent in the church, by the prayer of faith."],["D&C",28,14,"And thou shalt assist to settle all these things, according to the covenants of the church, before thou shalt take thy journey among the Lamanites."],["D&C",28,15,"And it shall be given thee from the time thou shalt go, until the time thou shalt return, what thou shalt do."],["D&C",28,16,"And thou must open thy mouth at all times, declaring my gospel with the sound of rejoicing. Amen."],["D&C",29,1,"Listen to the voice of Jesus Christ, your Redeemer, the Great I AM, whose arm of mercy hath atoned for your sins;"],["D&C",29,2,"Who will gather his people even as a hen gathereth her chickens under her wings, even as many as will hearken to my voice and humble themselves before me, and call upon me in mighty prayer."],["D&C",29,3,"Behold, verily, verily, I say unto you, that at this time your sins are forgiven you, therefore ye receive these things; but remember to sin no more, lest perils shall come upon you."],["D&C",29,4,"Verily, I say unto you that ye are chosen out of the world to declare my gospel with the sound of rejoicing, as with the voice of a trump."],["D&C",29,5,"Lift up your hearts and be glad, for I am in your midst, and am your advocate with the Father; and it is his good will to give you the kingdom."],["D&C",29,6,"And, as it is written—Whatsoever ye shall ask in faith, being united in prayer according to my command, ye shall receive."],["D&C",29,7,"And ye are called to bring to pass the gathering of mine elect; for mine elect hear my voice and harden not their hearts;"],["D&C",29,8,"Wherefore the decree hath gone forth from the Father that they shall be gathered in unto one place upon the face of this land, to prepare their hearts and be prepared in all things against the day when tribulation and desolation are sent forth upon the wicked."],["D&C",29,9,"For the hour is nigh and the day soon at hand when the earth is ripe; and all the proud and they that do wickedly shall be as stubble; and I will burn them up, saith the Lord of Hosts, that wickedness shall not be upon the earth;"],["D&C",29,10,"For the hour is nigh, and that which was spoken by mine apostles must be fulfilled; for as they spoke so shall it come to pass;"],["D&C",29,11,"For I will reveal myself from heaven with power and great glory, with all the hosts thereof, and dwell in righteousness with men on earth a thousand years, and the wicked shall not stand."],["D&C",29,12,"And again, verily, verily, I say unto you, and it hath gone forth in a firm decree, by the will of the Father, that mine apostles, the Twelve which were with me in my ministry at Jerusalem, shall stand at my right hand at the day of my coming in a pillar of fire, being clothed with robes of righteousness, with crowns upon their heads, in glory even as I am, to judge the whole house of Israel, even as many as have loved me and kept my commandments, and none else."],["D&C",29,13,"For a trump shall sound both long and loud, even as upon Mount Sinai, and all the earth shall quake, and they shall come forth—yea, even the dead which died in me, to receive a crown of righteousness, and to be clothed upon, even as I am, to be with me, that we may be one."],["D&C",29,14,"But, behold, I say unto you that before this great day shall come the sun shall be darkened, and the moon shall be turned into blood, and the stars shall fall from heaven, and there shall be greater signs in heaven above and in the earth beneath;"],["D&C",29,15,"And there shall be weeping and wailing among the hosts of men;"],["D&C",29,16,"And there shall be a great hailstorm sent forth to destroy the crops of the earth."],["D&C",29,17,"And it shall come to pass, because of the wickedness of the world, that I will take vengeance upon the wicked, for they will not repent; for the cup of mine indignation is full; for behold, my blood shall not cleanse them if they hear me not."],["D&C",29,18,"Wherefore, I the Lord God will send forth flies upon the face of the earth, which shall take hold of the inhabitants thereof, and shall eat their flesh, and shall cause maggots to come in upon them;"],["D&C",29,19,"And their tongues shall be stayed that they shall not utter against me; and their flesh shall fall from off their bones, and their eyes from their sockets;"],["D&C",29,20,"And it shall come to pass that the beasts of the forest and the fowls of the air shall devour them up."],["D&C",29,21,"And the great and abominable church, which is the whore of all the earth, shall be cast down by devouring fire, according as it is spoken by the mouth of Ezekiel the prophet, who spoke of these things, which have not come to pass but surely must, as I live, for abominations shall not reign."],["D&C",29,22,"And again, verily, verily, I say unto you that when the thousand years are ended, and men again begin to deny their God, then will I spare the earth but for a little season;"],["D&C",29,23,"And the end shall come, and the heaven and the earth shall be consumed and pass away, and there shall be a new heaven and a new earth."],["D&C",29,24,"For all old things shall pass away, and all things shall become new, even the heaven and the earth, and all the fulness thereof, both men and beasts, the fowls of the air, and the fishes of the sea;"],["D&C",29,25,"And not one hair, neither mote, shall be lost, for it is the workmanship of mine hand."],["D&C",29,26,"But, behold, verily I say unto you, before the earth shall pass away, Michael, mine archangel, shall sound his trump, and then shall all the dead awake, for their graves shall be opened, and they shall come forth—yea, even all."],["D&C",29,27,"And the righteous shall be gathered on my right hand unto eternal life; and the wicked on my left hand will I be ashamed to own before the Father;"],["D&C",29,28,"Wherefore I will say unto them—Depart from me, ye cursed, into everlasting fire, prepared for the devil and his angels."],["D&C",29,29,"And now, behold, I say unto you, never at any time have I declared from mine own mouth that they should return, for where I am they cannot come, for they have no power."],["D&C",29,30,"But remember that all my judgments are not given unto men; and as the words have gone forth out of my mouth even so shall they be fulfilled, that the first shall be last, and that the last shall be first in all things whatsoever I have created by the word of my power, which is the power of my Spirit."],["D&C",29,31,"For by the power of my Spirit created I them; yea, all things both spiritual and temporal—"],["D&C",29,32,"First spiritual, secondly temporal, which is the beginning of my work; and again, first temporal, and secondly spiritual, which is the last of my work—"],["D&C",29,33,"Speaking unto you that you may naturally understand; but unto myself my works have no end, neither beginning; but it is given unto you that ye may understand, because ye have asked it of me and are agreed."],["D&C",29,34,"Wherefore, verily I say unto you that all things unto me are spiritual, and not at any time have I given unto you a law which was temporal; neither any man, nor the children of men; neither Adam, your father, whom I created."],["D&C",29,35,"Behold, I gave unto him that he should be an agent unto himself; and I gave unto him commandment, but no temporal commandment gave I unto him, for my commandments are spiritual; they are not natural nor temporal, neither carnal nor sensual."],["D&C",29,36,"And it came to pass that Adam, being tempted of the devil—for, behold, the devil was before Adam, for he rebelled against me, saying, Give me thine honor, which is my power; and also a third part of the hosts of heaven turned he away from me because of their agency;"],["D&C",29,37,"And they were thrust down, and thus came the devil and his angels;"],["D&C",29,38,"And, behold, there is a place prepared for them from the beginning, which place is hell."],["D&C",29,39,"And it must needs be that the devil should tempt the children of men, or they could not be agents unto themselves; for if they never should have bitter they could not know the sweet—"],["D&C",29,40,"Wherefore, it came to pass that the devil tempted Adam, and he partook of the forbidden fruit and transgressed the commandment, wherein he became subject to the will of the devil, because he yielded unto temptation."],["D&C",29,41,"Wherefore, I, the Lord God, caused that he should be cast out from the Garden of Eden, from my presence, because of his transgression, wherein he became spiritually dead, which is the first death, even that same death which is the last death, which is spiritual, which shall be pronounced upon the wicked when I shall say: Depart, ye cursed."],["D&C",29,42,"But, behold, I say unto you that I, the Lord God, gave unto Adam and unto his seed, that they should not die as to the temporal death, until I, the Lord God, should send forth angels to declare unto them repentance and redemption, through faith on the name of mine Only Begotten Son."],["D&C",29,43,"And thus did I, the Lord God, appoint unto man the days of his probation—that by his natural death he might be raised in immortality unto eternal life, even as many as would believe;"],["D&C",29,44,"And they that believe not unto eternal damnation; for they cannot be redeemed from their spiritual fall, because they repent not;"],["D&C",29,45,"For they love darkness rather than light, and their deeds are evil, and they receive their wages of whom they list to obey."],["D&C",29,46,"But behold, I say unto you, that little children are redeemed from the foundation of the world through mine Only Begotten;"],["D&C",29,47,"Wherefore, they cannot sin, for power is not given unto Satan to tempt little children, until they begin to become accountable before me;"],["D&C",29,48,"For it is given unto them even as I will, according to mine own pleasure, that great things may be required at the hand of their fathers."],["D&C",29,49,"And, again, I say unto you, that whoso having knowledge, have I not commanded to repent?"],["D&C",29,50,"And he that hath no understanding, it remaineth in me to do according as it is written. And now I declare no more unto you at this time. Amen."],["D&C",30,1,"Behold, I say unto you, David, that you have feared man and have not relied on me for strength as you ought."],["D&C",30,2,"But your mind has been on the things of the earth more than on the things of me, your Maker, and the ministry whereunto you have been called; and you have not given heed unto my Spirit, and to those who were set over you, but have been persuaded by those whom I have not commanded."],["D&C",30,3,"Wherefore, you are left to inquire for yourself at my hand, and ponder upon the things which you have received."],["D&C",30,4,"And your home shall be at your father's house, until I give unto you further commandments. And you shall attend to the ministry in the church, and before the world, and in the regions round about. Amen."],["D&C",30,5,"Behold, I say unto you, Peter, that you shall take your journey with your brother Oliver; for the time has come that it is expedient in me that you shall open your mouth to declare my gospel; therefore, fear not, but give heed unto the words and advice of your brother, which he shall give you."],["D&C",30,6,"And be you afflicted in all his afflictions, ever lifting up your heart unto me in prayer and faith, for his and your deliverance; for I have given unto him power to build up my church among the Lamanites;"],["D&C",30,7,"And none have I appointed to be his counselor over him in the church, concerning church matters, except it is his brother, Joseph Smith, Jun."],["D&C",30,8,"Wherefore, give heed unto these things and be diligent in keeping my commandments, and you shall be blessed unto eternal life. Amen."],["D&C",30,9,"Behold, I say unto you, my servant John, that thou shalt commence from this time forth to proclaim my gospel, as with the voice of a trump."],["D&C",30,10,"And your labor shall be at your brother Philip Burroughs', and in that region round about, yea, wherever you can be heard, until I command you to go from hence."],["D&C",30,11,"And your whole labor shall be in Zion, with all your soul, from henceforth; yea, you shall ever open your mouth in my cause, not fearing what man can do, for I am with you. Amen."]]);
